function collectContentGroups(){
  const groups=new Map();
  contentScenes.forEach(scene=>{
    const project=scene.project==='imshop/아워레가시'?'imshop/OURLEGACY':scene.project;
    if(!groups.has(project))groups.set(project,{project,images:[]});
    const group=groups.get(project);
    scene.items.forEach(item=>group.images.push(...(item.gallery?editorialGalleries[item.gallery]||[item]:[item])));
  });
  return [...groups.values()].flatMap(group=>{
    const assets=[...(contentAdditionalAssets[group.project]||[]),...group.images].filter(item=>item.src==='images/content/9e69f583fefd.webp'||(!item.isPC&&item.src!=='images/content/d688f52f5ec7.webp'&&!/(?:^|[_\s])PC(?:[_.\s]|$)/i.test(item.sourceName||'')));
    const portrait=assets.find(item=>Math.abs(item.w/item.h-.8)<.015);
    const selectedCover={'obscura/Troentorp':'images/content/troentorp-05.webp','imshop/colecole':"images/content/2f3cdd3a42af.webp",'kasina/spiridon':'images/content/f424b483a022.webp','kasina/SALOMPN_SNS컨텐츠':'images/content/dd6bb924776e.webp'}[group.project];
    const cover=assets.find(item=>item.src===selectedCover)||portrait||contentCoverAssets[group.project]||assets[0];
    if(!cover)return [];
    const unique=new Map();
    [cover,...assets].forEach(item=>{if(!unique.has(item.src))unique.set(item.src,item)});
    return [{...group,cover,images:[...unique.values()]}];
  });
}
function renderContentFrame(){return renderContentCategories(collectContentGroups());}

function renderCardContribution(p){
 const items=[];
 if(p.designRole?.includes('KV 제작'))items.push('KEY VISUAL');
 if(p.designRole?.includes('페이지 디자인'))items.push('PAGE DESIGN');
 if(p.publishingCredit==='김한솔')items.push('FRONT-END');
 return items.length?items.join(' / '):'DESIGN';
}

