let transitionRunning=false;
function sync(animate=false){
  const slug=new URLSearchParams(location.search).get('project');
  const p=projects.find(p=>p.slug===slug);
  const closing=!p&&!detail.hidden;
  const activeSlug=p?.slug||detail.dataset.slug;
  const card=Array.from(document.querySelectorAll('[data-project]')).find(el=>el.dataset.project===activeSlug);
  const cardImage=card?.querySelector('.card-media img');
  const oldImage=closing?detail.querySelector('.detail-images img'):cardImage;
  const update=()=>{
    document.querySelectorAll('[data-transition-image]').forEach(el=>{el.style.viewTransitionName='';delete el.dataset.transitionImage;});
    if(p){showProject(p);detail.dataset.slug=p.slug;}else showList();
    const nextImage=p?detail.querySelector('.detail-images img'):cardImage;
    if(nextImage){nextImage.style.viewTransitionName='project-visual';nextImage.dataset.transitionImage='true';}
  };
  if(animate&&!closing&&!matchMedia('(max-width:850px)').matches&&!matchMedia('(prefers-reduced-motion: reduce)').matches&&!transitionRunning&&oldImage){
    transitionRunning=true;
    const before=oldImage.getBoundingClientRect();
    const floating=oldImage.cloneNode();
    floating.removeAttribute('loading');floating.removeAttribute('data-transition-image');
    floating.className='motion-image';floating.style.viewTransitionName='';floating.setAttribute('aria-hidden','true');
    update();
    const target=p?detail.querySelector('.project-screen-gallery img'):cardImage;
    const after=target.getBoundingClientRect();
    if(!after.width||!after.height){transitionRunning=false;return;}
    const actualVisibility=target.style.visibility;target.style.visibility='hidden';
    Object.assign(floating.style,{left:`${after.left}px`,top:`${after.top}px`,width:`${after.width}px`,height:`${after.height}px`});
    document.body.appendChild(floating);
    const dx=before.left-after.left,dy=before.top-after.top,sx=before.width/after.width,sy=before.height/after.height;
    const duration=1050,easing='cubic-bezier(.22,1,.36,1)';
    const anim=floating.animate([
      {transform:`translate(${dx}px,${dy}px) scale(${sx},${sy})`,opacity:1},
      {transform:`translate(${dx*.25}px,${dy*.22}px) scale(${sx+(1-sx)*.78},${sy+(1-sy)*.78}) perspective(1400px) rotateY(${closing?4:-5}deg) rotateZ(${closing?1.5:-2}deg)`,offset:.48,opacity:1},
      {transform:'translate(0,0) scale(1) perspective(1400px) rotateY(0deg) rotateZ(0deg)',opacity:1}
    ],{duration,easing,fill:'both'});
    if(p){
      detail.animate([{opacity:0},{opacity:1}],{duration:650,fill:'both'});
      detail.querySelector('.detail-aside').animate([{opacity:0,transform:'translateY(18px)'},{opacity:1,transform:'translateY(0)'}],{duration:700,delay:350,easing,fill:'both'});
      detail.querySelectorAll('.project-screen-gallery').forEach((el,i)=>el.animate([
        {opacity:0,transform:'perspective(1600px) translate(65px,100px) rotateY(-5deg) rotateZ(2deg)'},
        {opacity:1,transform:'perspective(1600px) translate(0,0) rotateY(0) rotateZ(0)'}
      ],{duration:1000,delay:180+Math.min(i,2)*90,easing,fill:'both'}));
    }
    anim.finished.catch(()=>{}).finally(()=>{target.style.visibility=actualVisibility;floating.remove();transitionRunning=false;document.querySelectorAll('[data-transition-image]').forEach(el=>{el.style.viewTransitionName='';delete el.dataset.transitionImage;});});
  }else update();
}
document.addEventListener('click',e=>{const a=e.target.closest('[data-project]');if(a&&transitionRunning){e.preventDefault();return;}if(a&&!transitionRunning&&!e.metaKey&&!e.ctrlKey&&!e.shiftKey&&!e.altKey){e.preventDefault();closeIndex();closeAbout();originLink=a;savedScroll=window.scrollY;history.replaceState({listScroll:savedScroll},'');history.pushState({project:a.dataset.project},'',`?project=${a.dataset.project}`);fromList=true;sync(true);}if(e.target.closest('[data-close]')){e.preventDefault();closeProject();}});
