window.addEventListener('message',event=>{if(event.origin!==location.origin||event.data?.type!=='portfolio-height')return;const frame=Array.from(detail.querySelectorAll('iframe')).find(f=>f.contentWindow===event.source);const h=Number(event.data.height);if(frame&&Number.isFinite(h)&&h>0&&h<200000){frame.dataset.contentHeight=h;sizeArchive(frame);}});

function sizeArchive(frame){const h=Number(frame.dataset.contentHeight)||900;if(frame.dataset.desktop){const width=1440;const scale=frame.parentElement.clientWidth/width;frame.style.width=`${width}px`;frame.style.transform=`scale(${scale})`;frame.style.transformOrigin='top left';frame.style.height=`${h}px`;frame.style.marginBottom=`${h*(scale-1)}px`;}else frame.style.height=`${h}px`;}
