// Transform independent color layers at different scroll speeds.
let gradientFrame=0;
const gradientMotion=matchMedia('(prefers-reduced-motion: reduce)');
function updateGradient(){gradientFrame=0;const hero=document.querySelector('.intro');if(!hero||!detail.hidden)return;const heroRect=hero.getBoundingClientRect();const offset=Math.max(0,-heroRect.top);const transitionStart=hero.offsetHeight*.2;const transitionEnd=hero.offsetHeight*.85;const fade=Math.min(1,Math.max(0,(offset-transitionStart)/Math.max(1,transitionEnd-transitionStart)));document.body.style.setProperty('--background-darkness',String(fade*fade*(3-2*fade)));const total=Math.max(1,document.documentElement.scrollHeight-innerHeight);const t=gradientMotion.matches?0:Math.min(1,window.scrollY/total);const phase=gradientMotion.matches?0:window.scrollY/Math.max(innerHeight,1);hero.style.setProperty('--gradient-y',`${Math.sin(phase*.6)*70}px`);hero.style.setProperty('--light-x',`${Math.sin(phase*.45)*240}px`);hero.style.setProperty('--light-y',`${Math.sin(phase*.35)*-140}px`);hero.style.setProperty('--light-scale',1+t*.4);hero.style.setProperty('--mint-x',`${Math.sin(phase*.4)*-150}px`);}
function queueGradient(){if(!gradientFrame)gradientFrame=requestAnimationFrame(updateGradient);}
window.addEventListener('scroll',queueGradient,{passive:true});window.addEventListener('resize',queueGradient);gradientMotion.addEventListener('change',queueGradient);queueGradient();

