// Reveal collection imagery as it enters the viewport, without trapping scroll.
let projectScrollFrame=0;
function updateProjectScroll(){projectScrollFrame=0;if(!detail.hidden)return;const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;document.querySelectorAll('.project-card').forEach(card=>{const media=card.querySelector('.card-media');const rect=media.getBoundingClientRect();if(rect.bottom< -150||rect.top>innerHeight+150)return;const reveal=reduced?1:Math.max(0,Math.min(1,(innerHeight-rect.top)/(innerHeight*.42)));const shift=reduced?0:Math.max(-10,Math.min(10,((innerHeight/2-(rect.top+rect.height/2))/innerHeight)*20));card.style.setProperty('--reveal',reveal.toFixed(3));card.style.setProperty('--image-shift',`${shift.toFixed(2)}px`);});}
function queueProjectScroll(){if(!projectScrollFrame)projectScrollFrame=requestAnimationFrame(updateProjectScroll);}
