let immersiveFrame=0;
function updateImmersive(){immersiveFrame=0;const root=document.querySelector('.content-immersive');if(!root||!detail.hidden)return;const scenes=[...root.querySelectorAll('.content-scene')];const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;if(reduced)return;const rect=root.getBoundingClientRect();const range=Math.max(1,root.offsetHeight-innerHeight);const progress=Math.max(0,Math.min(1,-rect.top/range));const position=progress*(scenes.length-1);scenes.forEach((scene,i)=>{const distance=i-position;const active=distance>-1&&distance<=1;scene.style.visibility=active?'visible':'hidden';scene.style.opacity=(distance<=0?1:Math.max(0,1-distance)).toFixed(3);scene.style.zIndex=String(i);scene.style.pointerEvents=active&&distance<=.5?'auto':'none';if(active){scene.style.transform=`translate3d(0,${distance*90}px,0) scale(${1-Math.abs(distance)*.06})`;scene.querySelectorAll('.scene-art').forEach((art,j)=>{art.style.transform=`translate3d(0,${distance*(j%2?100:-70)}px,0)`;});}});root.querySelector('.scene-progress i').style.transform=`scaleX(${progress})`;}
function queueImmersive(){if(!immersiveFrame)immersiveFrame=requestAnimationFrame(updateImmersive);}
window.addEventListener('scroll',queueImmersive,{passive:true});window.addEventListener('resize',queueImmersive);queueImmersive();

