document.addEventListener('click',e=>{const trigger=e.target.closest('[data-editorial]');if(!trigger)return;editorialOrigin=trigger;editorialIndex=0;const images=editorialGalleries[trigger.dataset.editorial];editorialDialog.innerHTML=`<div class="editorial-toolbar"><button data-editorial-close aria-label="이미지 모음 닫기">CLOSE ×</button></div><div class="editorial-scroll">${images.map((a,i)=>`<figure class="editorial-page"><img src="${a.src}" alt="에디토리얼 이미지 ${i+1}" width="${a.w}" height="${a.h}"></figure>`).join('')}</div><button class="editorial-prev" aria-label="이전 이미지">←</button><button class="editorial-next" aria-label="다음 이미지">→</button>`;editorialDialog.showModal();editorialDialog.querySelector('[data-editorial-close]').onclick=closeEditorial;editorialDialog.querySelector('.editorial-prev').onclick=()=>moveEditorial(-1);editorialDialog.querySelector('.editorial-next').onclick=()=>moveEditorial(1);const scroll=editorialDialog.querySelector('.editorial-scroll');scroll.addEventListener('scroll',()=>{const top=scroll.getBoundingClientRect().top;const pages=[...scroll.children];editorialIndex=pages.reduce((best,p,i)=>Math.abs(p.getBoundingClientRect().top-top)<Math.abs(pages[best].getBoundingClientRect().top-top)?i:best,0);},{passive:true});});
