function renderContentSlider(group){return `<div class="content-slider"><div class="content-slider-track" tabindex="0" aria-label="콘텐츠 시리즈 슬라이드">${group.images.map((item,index)=>`<figure class="content-slide"><button class="slide-enlarge" aria-label="이미지 크게 보기"><img src="${item.src}" width="${item.w}" height="${item.h}" alt="콘텐츠 시리즈 ${index+1}" loading="lazy" decoding="async"></button></figure>`).join('')}</div><div class="content-slider-controls"><button class="content-slide-prev" aria-label="이전 이미지">‹</button><span class="content-slide-count">1 / ${group.images.length}</span><button class="content-slide-next" aria-label="다음 이미지">›</button></div></div>`;}
document.addEventListener('click',event=>{const button=event.target.closest('.content-slide-prev,.content-slide-next');if(!button)return;const track=button.closest('.content-slider').querySelector('.content-slider-track');const step=track.children[0].getBoundingClientRect().width+parseFloat(getComputedStyle(track).columnGap||0);const index=Math.round(track.scrollLeft/step);const direction=button.classList.contains('content-slide-next')?1:-1;const next=(index+direction+track.children.length)%track.children.length;track.scrollTo({left:next*step,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'})});

function renderWorkflowCase(){const cases=[['발매 페이지 제작 프로세스 개선','온라인 기획 MD가 브랜드 담당자에게 발매 정보와 이미지 요청 → 브랜드 담당자가 자료를 취합해 디자이너에게 전달 → 정보 누락 시 디자이너가 추가 자료 재요청 → 확인과 재전달이 반복되어 제작 지연','브랜드 담당자가 데이터 시트를 직접 작성해 정보 누락과 소통 병목 감소 → 온라인·오프라인 MD가 슬랙 워크플로우로 요청 데이터 전달 → 데이터 시트를 AI에 전달해 페이지 제작 후 디자이너 검수','기존에는 담당자를 거쳐 전달받은 정보가 부족하면 디자이너가 필요한 정보를 다시 요청해야 했고, 확인과 재전달이 반복되는 병목이 발생했습니다. 브랜드 담당자가 데이터 시트를 직접 작성하도록 변경해 디자이너와의 소통 병목을 줄였습니다. 온라인·오프라인 MD의 슬랙 워크플로우 자동화로 요청 데이터를 연결하고, 디자이너가 AI에 데이터를 전달해 페이지 유형을 판단하고 기획전 코드를 생성합니다. 이후 디자이너와 기획자가 검수하고 페이지를 오픈합니다.',['데이터 시트 직접 작성','슬랙 워크플로우 자동화','AI 유형 판단 · 코드 생성','검수 · 페이지 오픈']],['요청 데이터 시트 제작','요청자와 제작자 간 기획 내용·에셋·조건 조율','데이터 시트를 통해 요청 정보를 구조화','요청자와 소통하기 위한 데이터 시트를 제작해 요청부터 제작까지 같은 정보를 기준으로 확인하도록 정리했습니다.',['시트 작성','정보 확인','제작','최종 확인']],['슬랙 업무 요청 자동화','요청 접수·기록·진행·완료 확인의 연결','슬랙 요청부터 시트 기록과 완료 액션까지 연결','슬랙 요청을 시트에 자동 기입하고, 업무 진행 후 슬랙에서 완료 액션으로 상태를 표시하는 흐름을 구성했습니다.',['슬랙 요청','시트 자동 기입','업무 진행','슬랙 완료']]];return `<div class="workflow-case">${cases.slice(0,1).map((item,index)=>`<article class="workflow-change" id="workflow-case-${index}"><h4>${item[0]}</h4>${index===0?`<p class="workflow-case-summary">브랜드 담당 MD가 데이터 시트를 직접 작성하도록 요청 방식을 정리했습니다. 슬랙 워크플로우로 요청을 전달하고, AI를 활용한 페이지 유형 판단과 코드 생성까지 제작 과정을 연결했습니다.</p>`:''}<div class="workflow-comparison"><div class="workflow-before"><span class="workflow-kicker">AS IS</span><h5>${index===0?'페이지 제작 30분 소요':'개선 전'}</h5><ol class="comparison-steps">${item[1].split(' → ').map(step=>`<li>${step}</li>`).join('')}</ol></div><span class="comparison-arrow" aria-hidden="true">${flowArrowIcon()}</span><div class="workflow-after"><span class="workflow-kicker">TO BE</span><h5>${index===0?'페이지 제작 10분 소요':'개선 후'}</h5><ol class="comparison-steps">${item[2].split(' → ').map(step=>`<li>${step}</li>`).join('')}</ol></div></div>${index!==0?`<p class="workflow-description">${item[3]}</p>`:''}${index===0?`<details class="workflow-supporting"><summary>제작 가이드와 템플릿 설계 보기</summary>${renderCodeVerifiedImprovements()+renderTypeDecisionFlow()}</details>`:''}<ol class="workflow-flow">${item[4].map(step=>`<li>${step}</li>`).join('')}</ol></article>`).join('')}${renderRequestProcessCase()}<article class="workflow-change brand-assets-case" id="workflow-brand-assets"><h4>브랜드 에셋 수집 자동화</h4><p class="workflow-description">입고대장 메일 확인부터 이미지 수집, 폴더 정리, PSD 파일 생성까지 자동화했습니다.<br>메일 자동화와 연결해 매번 홈페이지에서 이미지를 저장하고 제작 파일을 준비하던 반복 작업을 줄였습니다.</p><section class="asset-results" aria-label="브랜드 에셋 수집 자동화 성과"><div class="asset-results-heading"><span>작업 결과 · 에셋 10개 기준</span><h5>준비 시간 약 67% 단축</h5><p>자동화 실행 중에는 다른 작업을 병행합니다.</p></div><div class="asset-results-flow"><div class="asset-result-node"><span>기존 · 수동 작업</span><p>30<span>분</span></p></div><span class="asset-result-connector" aria-hidden="true">${flowArrowIcon()}</span><div class="asset-result-node is-improved"><span>개선 · 자동화</span><p>10<span>분</span></p></div></div></section><figure class="asset-automation-visual"><div class="workflow-flow-viewport" tabindex="0" role="region" aria-label="브랜드 에셋 자동화 흐름. 작은 화면에서 좌우로 스크롤할 수 있습니다."><img src="images/workflow/asset-collection-horizontal.svg?v=20261114-thirty-to-ten" width="1440" height="610" alt="이전: 입고대장 메일 확인, 홈페이지에서 이미지 저장, 폴더 정리, PSD 개별 생성. 개선: 입고 메일 자동화에서 수집 자동화로 연결해 이미지 수집과 폴더 정리, PSD 생성을 진행. 자동화 중 다른 작업 병행 가능. 10개 기준 30분에서 10분으로 단축." loading="lazy"></div><figcaption>에셋 10개 처리 기준</figcaption></figure></article><article class="workflow-change banner-guide-case" id="workflow-banner-guide"><h4>브랜드 배너 제작 운영가이드 제작-운영</h4><p class="workflow-description">제작 기준을 정리해 브랜드 표현의 일관성과 운영 효율 강화</p><section class="portfolio-guide-section"><figure class="portfolio-guide-document"><a href="images/workflow/guide-12.jpg" target="_blank" rel="noopener" aria-label="배너 제작 운영 가이드 원본 크게 보기"><img class="workflow-guide-image" src="images/workflow/guide-12.jpg" alt="빅배너 적용 예시와 운영 기준, 제작 요청부터 검수까지 정리한 실제 가이드" loading="lazy"></a></figure></section></article><div class="workflow-evidence"><a href="wireframes/workflow.html">가이드 · 템플릿 구성 보기 ↗</a></div></div>`;}

document.addEventListener('scroll',event=>{const track=event.target;if(!track.classList?.contains('content-slider-track'))return;const step=track.children[0].getBoundingClientRect().width+parseFloat(getComputedStyle(track).columnGap||0);const index=Math.min(track.children.length-1,Math.max(0,Math.round(track.scrollLeft/step)));track.closest('.content-slider').querySelector('.content-slide-count').textContent=`${index+1} / ${track.children.length}`},true);

const slideModal=document.createElement('dialog');slideModal.className='slide-modal';document.body.appendChild(slideModal);let modalImages=[],modalIndex=0,modalOrigin=null,modalVideoMode=false;function paintSlideModal(){slideModal.innerHTML=`<button class="slide-modal-close" aria-label="확대 이미지 닫기">CLOSE ×</button><div class="slide-modal-stage">${modalVideoMode?`<video class="slide-modal-image motion-modal-video" src="${modalImages[modalIndex]}" autoplay muted loop playsinline disablepictureinpicture disableremoteplayback controlslist="nodownload nofullscreen noremoteplayback" preload="metadata" aria-label="모션 그래픽 ${modalIndex+1}"></video>`:`<img class="slide-modal-image" src="${modalImages[modalIndex]}" alt="확대 이미지 ${modalIndex+1}">`}<div class="slide-modal-controls"${modalImages.length<2?' hidden':''}><button data-modal-step="-1" aria-label="이전 이미지"><span aria-hidden="true"></span></button><button data-modal-step="1" aria-label="다음 이미지"><span aria-hidden="true"></span></button></div></div>`}function stepSlideModal(delta){modalIndex=(modalIndex+delta+modalImages.length)%modalImages.length;paintSlideModal()}function closeSlideModal(){slideModal.querySelectorAll('video').forEach(video=>video.pause());slideModal.close();slideModal.innerHTML='';modalVideoMode=false;document.body.classList.remove('slide-modal-open');if(modalOrigin){const origin=modalOrigin;origin.classList.add('modal-focus-return');origin.focus({preventScroll:true});origin.addEventListener('blur',()=>origin.classList.remove('modal-focus-return'),{once:true})}}document.addEventListener('click',event=>{const trigger=event.target.closest('.slide-enlarge');if(!trigger)return;modalVideoMode=false;modalOrigin=trigger;const buttons=[...trigger.closest('.content-slider-track').querySelectorAll('.slide-enlarge')];modalImages=buttons.map(button=>button.querySelector('img').src);modalIndex=buttons.indexOf(trigger);paintSlideModal();slideModal.showModal();document.body.classList.add('slide-modal-open')});slideModal.addEventListener('click',event=>{if(event.target.closest('.slide-modal-close')||event.target===slideModal)closeSlideModal();const step=event.target.closest('[data-modal-step]');if(step)stepSlideModal(Number(step.dataset.modalStep))});slideModal.addEventListener('cancel',event=>{event.preventDefault();closeSlideModal()});slideModal.addEventListener('keydown',event=>{if(event.key==='ArrowLeft'){event.preventDefault();stepSlideModal(-1)}if(event.key==='ArrowRight'){event.preventDefault();stepSlideModal(1)}});let modalTouchX=0;slideModal.addEventListener('touchstart',event=>{modalTouchX=event.changedTouches[0].clientX},{passive:true});slideModal.addEventListener('touchend',event=>{const delta=event.changedTouches[0].clientX-modalTouchX;if(Math.abs(delta)>50)stepSlideModal(delta<0?1:-1)},{passive:true});

function renderWorkflowComparison(rows){
 const panel=(row,index)=>`<div class="${index===0?'workflow-before':'workflow-after'}"><span class="workflow-kicker">${row.label}</span><h5>${index===0?'개선 전':'개선 후'}${row.time?' · '+row.time:''}</h5><ol class="comparison-steps">${row.steps.map(step=>`<li>${step[0]} · ${step[1]}</li>`).join('')}</ol></div>`;
 return `<div class="workflow-comparison">${panel(rows[0],0)}<span class="comparison-arrow" aria-hidden="true">${flowArrowIcon()}</span>${panel(rows[1],1)}</div>`;
}
