// Native horizontal scrolling supports touch, trackpads and keyboard navigation.
function moveContentCarousel(root,direction){
 const track=root.querySelector('.content-carousel-track');
 const cards=[...track.children];if(!cards.length)return;
 const gap=parseFloat(getComputedStyle(track).columnGap)||0;
 const step=cards[0].getBoundingClientRect().width+gap;
 track.scrollBy({left:direction*step,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});
}
document.addEventListener('click',event=>{
 const button=event.target.closest('[data-content-step]');if(!button)return;
 moveContentCarousel(button.closest('.content-carousel'),Number(button.dataset.contentStep));
});
document.addEventListener('keydown',event=>{
 if(!event.target.matches('.content-carousel-track')||!['ArrowLeft','ArrowRight'].includes(event.key))return;
 event.preventDefault();moveContentCarousel(event.target.closest('.content-carousel'),event.key==='ArrowRight'?1:-1);
});

// Reveal each before/after comparison once, in reading order.
const workflowMotionPreference=matchMedia('(prefers-reduced-motion: reduce)');
function initWorkflowComparisonMotion(){
 const comparisons=[...document.querySelectorAll('.workflow-comparison')];
 if(workflowMotionPreference.matches||!('IntersectionObserver' in window))return;
 const observer=new IntersectionObserver(entries=>{
  entries.forEach(entry=>{
   if(!entry.isIntersecting)return;
   const comparison=entry.target;
   comparison.classList.add('comparison-visible');
   observer.unobserve(comparison);
  });
 },{threshold:.15});
 comparisons.forEach(comparison=>{
  comparison.querySelectorAll('.comparison-steps').forEach(list=>{
   [...list.children].forEach((step,index)=>step.style.setProperty('--step-delay',`${index*100}ms`));
  });
  comparison.classList.add('comparison-motion');
  observer.observe(comparison);
 });
 workflowMotionPreference.addEventListener('change',()=>{
  if(!workflowMotionPreference.matches)return;
  observer.disconnect();comparisons.forEach(comparison=>comparison.classList.remove('comparison-motion'));
 });
}
initWorkflowComparisonMotion();

// Shared, restrained entrance motion for the portfolio collection and case studies.
function initPortfolioMotion(){
 const preference=matchMedia('(prefers-reduced-motion: reduce)');
 if(preference.matches||!('IntersectionObserver' in window))return;
 const targets=[...document.querySelectorAll('.category-heading,.project-card,.content-archive-card,.workflow-overview>a,.workflow-process-visual,.asset-automation-visual,.workflow-change>h4,.workflow-flow>li,.asset-results,.routing-heading,.routing-branch,.about-section .meta-block')];
 const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{
  if(!entry.isIntersecting)return;
  entry.target.classList.add('motion-shown');observer.unobserve(entry.target);
 }),{threshold:.08});
 targets.forEach((element,index)=>{
  element.style.setProperty('--entrance-delay',`${element.matches('.content-archive-card,.workflow-flow>li')?Math.min(index%3,2)*70:0}ms`);
  element.classList.add('motion-ready');observer.observe(element);
  element.addEventListener('focusin',()=>element.classList.add('motion-shown'),{once:true});
 });
 preference.addEventListener('change',()=>{if(preference.matches){observer.disconnect();targets.forEach(el=>el.classList.remove('motion-ready'));}});
}
initPortfolioMotion();



function renderMotionGraphics(){return `<section id="motion-graphics" class="content-discipline content-carousel motion-graphics-section" aria-label="Motion Graphics 슬라이드"><h3>Motion Graphics<span>${motionProjects.length} projects</span></h3><div class="content-carousel-toolbar">${renderPreviewControls(motionProjects.length).replaceAll('data-preview-step','data-content-step')}</div><div class="content-carousel-track" tabindex="0" aria-label="Motion Graphics 프로젝트 슬라이드">${motionProjects.map((project,index)=>{const media=project.videos[0];return `<article class="content-archive-card motion-card"><button class="motion-art-open" data-motion-project="${index}" aria-label="${project.title} 영상 크게 보기"><span class="archive-art-media"><video class="motion-preview" width="${media.w}" height="${media.h}" data-src="${media.src}" poster="${media.poster}" muted loop playsinline disablepictureinpicture disableremoteplayback preload="none" aria-label="${project.title} 미리보기"></video>${project.videos.length>1?`<span class="content-image-badge">+${project.videos.length}</span>`:''}</span><span class="archive-art-caption"><span>${project.title}</span></span></button></article>`}).join('')}</div></section>`;}
document.addEventListener('click',event=>{
 const trigger=event.target.closest('[data-motion-project]');if(!trigger)return;
 const project=motionProjects[Number(trigger.dataset.motionProject)];
 modalOrigin=trigger;modalVideoMode=true;modalIndex=0;modalImages=project.videos.map(video=>video.src);
 document.querySelectorAll('.motion-preview').forEach(video=>video.pause());
 paintSlideModal();slideModal.showModal();document.body.classList.add('slide-modal-open');
});
function initMotionPreviews(){
 const videos=[...document.querySelectorAll('.motion-preview')];
 let active=null;
 function syncVideos(){
  const paused=document.hidden||!!document.querySelector('dialog[open]')||document.body.classList.contains('detail-open');
  videos.forEach(video=>{
   if(paused||video!==active){video.pause();return;}
   if(!video.getAttribute('src'))video.src=video.dataset.src;
   video.muted=true;video.play().catch(()=>{});
  });
 }
 videos.forEach(video=>{
  const button=video.closest('.motion-art-open');
  button.addEventListener('pointerenter',event=>{if(event.pointerType!=='mouse')return;active=video;syncVideos()});
  button.addEventListener('pointerleave',()=>{if(active===video)active=null;syncVideos()});
  button.addEventListener('focus',()=>{if(button.matches(':focus-visible')){active=video;syncVideos()}});
  button.addEventListener('blur',()=>{if(active===video)active=null;syncVideos()});
 });
 document.addEventListener('visibilitychange',syncVideos);
 new MutationObserver(syncVideos).observe(document.body,{attributes:true,attributeFilter:['class']});
}

initMotionPreviews();

// Give local wheel navigation a short, controlled glide.
function initScrollLinkedCarousels(){
 const preference=matchMedia('(prefers-reduced-motion: reduce)');
 document.querySelectorAll('.content-carousel').forEach(root=>{
  const track=root.querySelector('.content-carousel-track');
  let frame=0,target=track.scrollLeft,settleTimer=0,lastTime=0;
  function stop(){cancelAnimationFrame(frame);frame=0;clearTimeout(settleTimer);track.classList.remove('is-scroll-driven');target=track.scrollLeft;}
  function glide(time){
   const elapsed=lastTime?Math.min(48,time-lastTime):16;lastTime=time;
   const distance=target-track.scrollLeft;
   if(Math.abs(distance)<.8){track.scrollLeft=target;frame=0;settleTimer=setTimeout(()=>track.classList.remove('is-scroll-driven'),120);return;}
   track.scrollLeft+=distance*(1-Math.exp(-elapsed/65));frame=requestAnimationFrame(glide);
  }
  root.addEventListener('wheel',event=>{
   if(event.ctrlKey||preference.matches||document.querySelector('dialog[open]')||document.body.classList.contains('detail-open'))return;
   if(Math.abs(event.deltaX)>=Math.abs(event.deltaY)){stop();return;}
   const max=track.scrollWidth-track.clientWidth;if(max<=1)return;
   if(!frame)target=track.scrollLeft;
   const unit=event.deltaMode===1?16:event.deltaMode===2?track.clientHeight:1;
   const next=Math.max(0,Math.min(max,target+event.deltaY*unit));
   if(Math.abs(next-target)<.5){if(frame)event.preventDefault();return;}
   event.preventDefault();target=next;clearTimeout(settleTimer);
   root.dataset.scrollDrivenUntil=String(Date.now()+4500);
   track.classList.add('is-scroll-driven');
   if(!frame){lastTime=0;frame=requestAnimationFrame(glide);}
  },{passive:false});
  root.addEventListener('pointerdown',stop,{passive:true});root.addEventListener('keydown',stop);
  preference.addEventListener('change',stop);
  document.addEventListener('visibilitychange',()=>{if(document.hidden)stop()});
 });
}
// Scroll-linked navigation is disabled; automatic sliding is active.

// Trace workflow stages in reading order without moving or hiding the content.
function initWorkflowStageMotion(){
 const preference=matchMedia('(prefers-reduced-motion: reduce)');
 if(preference.matches||!('IntersectionObserver' in window))return;
 const rows=[...document.querySelectorAll('.guide-workflow-track,.workflow-flow')];
 const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{
  if(!entry.isIntersecting)return;
  entry.target.classList.add('flow-sequence-active');observer.unobserve(entry.target);
 }),{threshold:.3});
 rows.forEach(row=>{[...row.children].forEach((node,index)=>node.style.setProperty('--flow-delay',`${index*160}ms`));observer.observe(row)});
 preference.addEventListener('change',()=>{if(preference.matches){observer.disconnect();rows.forEach(row=>row.classList.remove('flow-sequence-active'));}});
}
initWorkflowStageMotion();

function initContentAutoSlide(){
 const preference=matchMedia('(prefers-reduced-motion: reduce)');
 document.querySelectorAll('.content-carousel').forEach(root=>{
  const track=root.querySelector('.content-carousel-track');
  if(!track||track.children.length<2)return;
  let visible=false,interacting=false,resumeAt=0;
  const pause=()=>{resumeAt=Date.now()+8000};
  if('IntersectionObserver' in window){
   const observer=new IntersectionObserver(entries=>{visible=entries[0].isIntersecting},{threshold:.2});observer.observe(track);
  }else visible=true;
  root.addEventListener('pointerdown',()=>{interacting=true;pause()});
  window.addEventListener('pointerup',()=>{if(interacting){interacting=false;pause()}});
  window.addEventListener('pointercancel',()=>{interacting=false;pause()});
  root.addEventListener('wheel',pause,{passive:true});root.addEventListener('keydown',pause);
  setInterval(()=>{
   if(preference.matches||document.hidden||!visible||interacting||Date.now()<resumeAt||root.querySelector(':focus-visible')||document.querySelector('dialog[open]')||document.body.classList.contains('detail-open'))return;
   if(root.classList.contains('motion-graphics-section')&&root.matches(':hover'))return;
   const max=track.scrollWidth-track.clientWidth;if(max<=1)return;
   if(track.scrollLeft>=max-2)track.scrollTo({left:0,behavior:'smooth'});else moveContentCarousel(root,1);
  },4500);
 });
}
initContentAutoSlide();

// Suppress only the outline restored by the image dialog, not keyboard navigation.
document.addEventListener('keydown',event=>{
 if(event.key==='Tab')document.querySelectorAll('.modal-focus-return').forEach(element=>element.classList.remove('modal-focus-return'));
});

// Make carousel boundaries visible instead of leaving dead arrow controls.
function initCarouselBoundaries(){
 document.querySelectorAll('.content-carousel').forEach(root=>{
  const track=root.querySelector('.content-carousel-track');
  const previous=root.querySelector('[data-content-step="-1"]');
  const next=root.querySelector('[data-content-step="1"]');
  if(!track||!previous||!next)return;
  let frame=0;
  function update(){
   frame=0;const max=Math.max(0,track.scrollWidth-track.clientWidth);
   previous.disabled=track.scrollLeft<=2;next.disabled=max<=2||track.scrollLeft>=max-2;
  }
  function queue(){if(!frame)frame=requestAnimationFrame(update)}
  track.addEventListener('scroll',queue,{passive:true});
  if('ResizeObserver' in window)new ResizeObserver(queue).observe(track);
  update();
 });
}
initCarouselBoundaries();

// Header anchors also work while a project detail route is open.
document.querySelectorAll('.site-header a[href^="#"]').forEach(link=>{
 link.addEventListener('click',event=>{
  if(event.metaKey||event.ctrlKey||event.shiftKey||event.altKey)return;
  const target=document.getElementById(link.hash.slice(1));if(!target)return;
  if(detail.hidden)return;
  event.preventDefault();
  fromList=false;originLink=null;
  history.replaceState(null,'',location.pathname+link.hash);
  showList();
  requestAnimationFrame(()=>target.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'}));
 });
});

// Folding section index.
const indexToggle=document.querySelector('.index-toggle');
const indexPanel=document.querySelector('#index-panel');
let indexCollapseAnimation=null,indexOpenedAt=0,indexScrollOrigin=window.scrollY;
function closeIndex(){if(indexCollapseAnimation){indexCollapseAnimation.cancel();indexCollapseAnimation=null;}indexToggle.setAttribute('aria-expanded','false');indexPanel.hidden=true;document.body.classList.toggle('navigation-open',!document.querySelector('#about').hidden);}
indexToggle.addEventListener('click',()=>{const open=indexToggle.getAttribute('aria-expanded')!=='true';indexToggle.setAttribute('aria-expanded',String(open));indexPanel.hidden=!open;document.body.classList.toggle('navigation-open',open);if(open){if(indexCollapseAnimation){indexCollapseAnimation.cancel();indexCollapseAnimation=null;}indexOpenedAt=performance.now();indexScrollOrigin=window.scrollY;document.querySelector('#about').hidden=true;document.querySelector('.about-toggle').setAttribute('aria-expanded','false');if(!detail.hidden){fromList=false;originLink=null;history.replaceState(null,'',location.pathname);showList();}positionNavigationPanel();}});
indexPanel.addEventListener('click',event=>{const yearLink=event.target.closest('[data-index-year]');if(yearLink){event.preventDefault();const year=yearLink.dataset.indexYear;document.querySelectorAll('#pages [data-project]').forEach(card=>{card.hidden=projects.find(project=>project.slug===card.dataset.project)?.year!==year});closeIndex();document.querySelector('#pages').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});return;}const anyLink=event.target.closest('a');if(anyLink&&!anyLink.hash){closeIndex();return;}const link=event.target.closest('a[href^="#"]');if(!link)return;event.preventDefault();if(link.hash==='#pages'||link.hash==='#work')document.querySelectorAll('#pages [data-project]').forEach(card=>card.hidden=false);closeIndex();if(!detail.hidden){fromList=false;originLink=null;history.replaceState(null,'',location.pathname+link.hash);showList();}else history.replaceState(null,'',location.pathname+link.hash);requestAnimationFrame(()=>document.querySelector(link.hash)?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'}));});
document.addEventListener('click',event=>{if(!indexPanel.hidden&&!indexPanel.contains(event.target)&&!indexToggle.contains(event.target))closeIndex();});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!indexPanel.hidden){closeIndex();indexToggle.focus();}});

indexPanel.querySelectorAll('[data-index-sort]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('#pages [data-project]').forEach(card=>card.hidden=false);const direction=button.dataset.indexSort==='latest'?-1:1;const grid=document.querySelector('#pages .project-grid');[...grid.children].sort((a,b)=>{const year=card=>projects.find(p=>p.slug===card.dataset.project)?.year||0;return direction*(year(a)-year(b));}).forEach(card=>grid.appendChild(card));closeIndex();document.querySelector('#pages').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});}));

const aboutToggle=document.querySelector('.about-toggle');
const aboutPanel=document.querySelector('#about');
function closeAbout(){if(location.hash==='#about')history.replaceState(history.state,'',location.pathname+location.search);aboutPanel.hidden=true;aboutToggle.setAttribute('aria-expanded','false');document.body.classList.toggle('navigation-open',!indexPanel.hidden);}
aboutToggle.addEventListener('click',()=>{const open=aboutPanel.hidden;closeIndex();aboutPanel.hidden=!open;aboutToggle.setAttribute('aria-expanded',String(open));document.body.classList.toggle('navigation-open',open);if(open){if(!detail.hidden){fromList=false;originLink=null;showList();}history.replaceState(null,'',location.pathname+'#about');positionNavigationPanel();}else history.replaceState(null,'',location.pathname);});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!aboutPanel.hidden){closeAbout();aboutToggle.focus();}});
if(location.hash==='#about')aboutToggle.click();

function positionNavigationPanel(){const header=document.querySelector('.site-header');document.documentElement.style.setProperty('--navigation-top',`${header.getBoundingClientRect().bottom}px`);}
window.addEventListener('resize',()=>{if(document.body.classList.contains('navigation-open'))positionNavigationPanel();});

// Dismiss the index gently when the page is scrolled downward.
window.addEventListener('scroll',()=>{
 const y=window.scrollY;
 if(indexPanel.hidden||indexCollapseAnimation){indexScrollOrigin=y;return;}
 if(performance.now()-indexOpenedAt<350){indexScrollOrigin=y;return;}
 if(y<indexScrollOrigin){indexScrollOrigin=y;return;}
 if(y-indexScrollOrigin<16)return;
 if(matchMedia('(prefers-reduced-motion: reduce)').matches){closeIndex();return;}
 const animation=indexPanel.animate([{opacity:1,transform:'translateY(0)'},{opacity:0,transform:'translateY(-12px)'}],{duration:220,easing:'cubic-bezier(.22,1,.36,1)',fill:'forwards'});
 indexCollapseAnimation=animation;
 animation.finished.then(()=>{if(indexCollapseAnimation===animation)closeIndex();}).catch(()=>{});
},{passive:true});
